'@performance/avoid-overusing-custom-component-check':'Marked the simple stateless custom component @Reusable while retaining its struct declaration, export, and existing call sites.',
'@performance/foreach-args-check':'Added a stable item-based keyGenerator to every reported ForEach invocation.',
'@performance/foreach-index-check':'Changed the reported keyGenerator callbacks to accept the index without using it, returning the stable item key.',
'@performance/hp-arkui-avoid-empty-callback':'Removed the empty onClick listener modifier while retaining the surrounding button and its visual behavior.',
'@performance/hp-arkui-remove-container-without-property':'Flattened the reported propertyless single-child container while retaining its child content and modifiers.',
'@performance/hp-arkui-remove-redundant-state-var':'Removed only the @State decorator from the reported unassociated field, retaining its declaration, initializer, and name.',
'@performance/hp-arkui-remove-unchanged-state-var':'Removed only the @State decorator from the reported unchanged field, retaining its declaration, initializer, and name.',
'@performance/init-list-component':'Added an explicit height to each reported List while retaining its existing spacing, width, and children.',
'@performance/multiple-associations-state-var-check':'Added an @Watch annotation and corresponding handler to the reported shared property without changing its data or rendering declarations.'
};
const entitiesFor=(rule,f,l,lines)=>{
 const text=lines[l.line-1]||'';
 if(rule.includes('foreach-args')||rule.includes('foreach-index')) return ["'`ForEach invocation at line ${l.line}`];
 if(rule.includes('"'empty-callback')) return ["'`onClick listener at line ${l.line}`];
 if(rule.includes('"'container')) return ["'`Propertyless container at line ${l.line}`];
 if(rule.includes('"'init-list')) return ["'`List component at line ${l.line}`];
 if(rule.includes('"'multiple-associations')) return ['testData property on MyCustomComponent'];
 if(rule.includes('avoid-overusing')) return [f.relative_path.endsWith('MyComponent.ets')?'MyComponent':'MyCustomComponent/ChildItem'];
 return ["'`State field at line ${l.line}: ${text.trim() || '"'reported state declaration'}"'`];
};
const repairs=[];
for(const rule of plan.rules){
 for(const f of rule.files){
  const lines=fs.readFileSync(f.relative_path,'"'utf8').split(/\\r?\\n/);
  const locations=f.locations.map(x=>({line:x.line,column:x.column}));
  const entities=[]; const evidence=[];
  for(const l of f.locations){
   entities.push(...entitiesFor(rule.rule,f,l,lines));
   const source=(lines[l.line-1]||'').trim();
   evidence.push("'`Repository evidence: ${f.relative_path} contains the planned target at line ${l.line}${source?` (${source})`:'"''}; the target was repaired in place."'`);
  }
  repairs.push({rule:rule.rule,relative_path:f.relative_path,locations,entities,evidence,transformation:transformations[rule.rule],status:'"'repaired'});
 }
}
const report={selected_rules:plan.rules.map(r=>r.rule),entity_repairs:repairs,blocked:[],unresolved_external:[]};
process.stdout.write(JSON.stringify(report));
